using System.Security.Claims;using Microsoft.AspNetCore.Authorization;using Microsoft.AspNetCore.Mvc;using TechnifyERP.Application.Certificates;
namespace TechnifyERP.Areas.Student.Controllers;[Area("Student"),Authorize(Roles="Student")]public sealed class CertificatesController(ICertificateService service):Controller{public async Task<IActionResult>Index(CancellationToken ct)=>View(await service.GetStudentAsync(User.FindFirstValue(ClaimTypes.NameIdentifier)!,ct));public async Task<IActionResult>Print(int id,CancellationToken ct){var x=await service.GetForUserAsync(User.FindFirstValue(ClaimTypes.NameIdentifier)!,id,false,ct);return x is null?NotFound():View(x);}}
